import json
'Observable policy for pour_liquid_into_cup.\n\ncamera calibration, robot proprioception, and allowlisted tools.'
import math
import numpy as np
LAST_DIAGNOSTICS = {}

# RGB defaults in metres. Bottle height is the self-play measurement below.
# The other defaults are the geometry fit for this task.
# Directed self-play: docs/self_play_estimates/reports/manifest.json
FALLBACK_BOTTLE_HEIGHT_M = 0.21886  # +/-0.004, base to mouth.
FALLBACK_RIM_HEIGHT_M = 0.076  # +/-0.0032, above local support.
FALLBACK_CUP_EXTENT_M = 0.100  # +/-0.005, includes the handle.
SPOUT_OUTER_RADIUS_M = 0.015  # +/-0.0015, outer lip, not inner opening.
FALLBACK_SUPPORT_Z = 0.766  # +/-0.0025, world z near the observed objects.

def _unit(vec):
    """Return unit 3-vector or default +z if norm is degenerate."""
    v = np.asarray(vec, dtype=float).reshape(-1)[:3]
    n = float(np.linalg.norm(v))
    if n < 1e-09 or not np.all(np.isfinite(v)):
        return np.array([0.0, 0.0, 1.0], dtype=float)
    return v / n

def _quat_to_mat(q):
    """Convert [w, x, y, z] quaternion to a 3x3 rotation matrix."""
    q = np.asarray(q, dtype=float).reshape(-1)[:4]
    norm = float(np.linalg.norm(q))
    if norm < 1e-09:
        return np.eye(3, dtype=float)
    w, x, y, z = q / norm
    return np.array([[1.0 - 2.0 * (y * y + z * z), 2.0 * (x * y - z * w), 2.0 * (x * z + y * w)], [2.0 * (x * y + z * w), 1.0 - 2.0 * (x * x + z * z), 2.0 * (y * z - x * w)], [2.0 * (x * z - y * w), 2.0 * (y * z + x * w), 1.0 - 2.0 * (x * x + y * y)]], dtype=float)

def _rpy_to_eef_mat(pitch_deg=0.0, yaw_deg=0.0, roll_deg=0.0):
    """Compute this library's end-effector 3x3 rotation matrix: Rz(90 + yaw) @ Ry(pitch) @ Rx(roll)."""
    alpha = math.radians(90.0 + float(yaw_deg))
    beta = math.radians(float(pitch_deg))
    gamma = math.radians(float(roll_deg))
    ca, sa = (math.cos(alpha), math.sin(alpha))
    cb, sb = (math.cos(beta), math.sin(beta))
    cg, sg = (math.cos(gamma), math.sin(gamma))
    rz = np.array([[ca, -sa, 0.0], [sa, ca, 0.0], [0.0, 0.0, 1.0]], dtype=float)
    ry = np.array([[cb, 0.0, sb], [0.0, 1.0, 0.0], [-sb, 0.0, cb]], dtype=float)
    rx = np.array([[1.0, 0.0, 0.0], [0.0, cg, -sg], [0.0, sg, cg]], dtype=float)
    return rz @ ry @ rx

def _pouring_lip_unit_vec(r_bottle, sign):
    """Return the unit vector in the bottle mouth plane pointing to the lower pouring lip."""
    a_b = _unit(r_bottle @ np.array([0.0, 0.0, 1.0], dtype=float))
    cand = np.array([float(sign) * a_b[2], 0.0, -float(sign) * a_b[0]], dtype=float)
    cand = cand - float(np.dot(cand, a_b)) * a_b
    norm = float(np.linalg.norm(cand))
    if norm < 1e-06:
        cand = np.array([0.0, 0.0, -1.0], dtype=float)
        cand = cand - float(np.dot(cand, a_b)) * a_b
    return _unit(cand)

def _episode_active(robo):
    """Return whether the benchmark has left the episode active."""
    try:
        return not bool(robo.state().truncated)
    except Exception:
        return False

def _is_termination_exc(exc):
    """Check whether an exception signals normal episode completion."""
    name = type(exc).__name__.lower()
    msg = str(exc).lower()
    return any((tok in name or tok in msg for tok in ('episodefinished', 'truncated', 'finished', 'terminated')))

def _preview_ok(robo, xyz, *, arm, pitch=0.0, yaw=0.0, roll=0.0, path='line'):
    """Return (ok_bool, preview_dict) for a candidate move."""
    target = [round(float(xyz[0]), 4), round(float(xyz[1]), 4), round(float(xyz[2]), 4)]
    try:
        pm = robo.preview_move(target, arm=arm, pitch=float(pitch), yaw=float(yaw), roll=float(roll), path=path)
        if isinstance(pm, dict):
            ok = bool(pm.get('reachable', False)) and pm.get('ik_error') is None
            return (ok, pm)
        return (False, {})
    except Exception as exc:
        if _is_termination_exc(exc):
            return (False, {'terminated': True})
        return (False, {})

def _safe_move(robo, xyz, *, arm, gripper, pitch=0.0, yaw=0.0, roll=0.0, prefer_path='line'):
    """Execute a bounded move_to after checking preview_move reachability and path fallback."""
    if not _episode_active(robo):
        return None
    target = [round(float(xyz[0]), 4), round(float(xyz[1]), 4), round(float(xyz[2]), 4)]
    chosen_path = prefer_path
    alt_path = 'auto' if prefer_path == 'line' else 'line'
    ok_pref, pm_pref = _preview_ok(robo, target, arm=arm, pitch=pitch, yaw=yaw, roll=roll, path=prefer_path)
    if pm_pref.get('terminated'):
        return None
    if not ok_pref:
        ok_alt, pm_alt = _preview_ok(robo, target, arm=arm, pitch=pitch, yaw=yaw, roll=roll, path=alt_path)
        if pm_alt.get('terminated'):
            return None
        if ok_alt:
            chosen_path = alt_path
        else:
            return None
    try:
        res = robo.move_to(target, arm=arm, gripper=gripper, pitch=float(pitch), yaw=float(yaw), roll=float(roll), path=chosen_path)
        if res is not None and (not getattr(res, 'truncated', False)):
            need_retry = not getattr(res, 'reached', True) or getattr(res, 'ik_error', None) is not None or getattr(res, 'blocked', False)
            if need_retry and chosen_path == 'line' and _episode_active(robo):
                res = robo.move_to(target, arm=arm, gripper=gripper, pitch=float(pitch), yaw=float(yaw), roll=float(roll), path='auto')
        if res is not None and (not getattr(res, 'reached', False)):
            return None
        return res
    except Exception as exc:
        if _is_termination_exc(exc):
            return None
        raise

def _safe_grip(robo, arm, gripper_cmd):
    """Execute a bounded set_gripper call with termination handling."""
    if not _episode_active(robo):
        return None
    try:
        return robo.set_gripper(arm, gripper_cmd)
    except Exception as exc:
        if _is_termination_exc(exc):
            return None
        raise

def _dwell(robo, idle_arm, num_calls):
    """Advance simulation time while holding the pouring arm steady."""
    for _ in range(int(num_calls)):
        if not _episode_active(robo):
            break
        res = _safe_grip(robo, idle_arm, robo.OPEN)
        if res is None or getattr(res, 'truncated', False):
            break

def _pixel_to_world_ray(meta, row, col):
    """Convert pixel (row, col) to (cam_origin_xyz, ray_dir_world_unit) using camera_meta."""
    K = np.asarray(meta['intrinsic_matrix'], dtype=float).reshape(3, 3)
    T = np.asarray(meta['extrinsic_matrix'], dtype=float).reshape(4, 4)
    fx, fy = (float(K[0, 0]), float(K[1, 1]))
    cx, cy = (float(K[0, 2]), float(K[1, 2]))
    x_cam = (float(col) - cx) / max(fx, 1e-06)
    y_cam = -(float(row) - cy) / max(fy, 1e-06)
    z_cam = -1.0
    d_cam = _unit([x_cam, y_cam, z_cam])
    r_c2w = T[:3, :3]
    origin_w = T[:3, 3].copy()
    dir_w = _unit(r_c2w @ d_cam)
    return (origin_w, dir_w)

def _world_to_pixel(meta, xyz):
    """Project a 3D world point [x, y, z] into (row, col) of camera_meta."""
    K = np.asarray(meta['intrinsic_matrix'], dtype=float).reshape(3, 3)
    T = np.asarray(meta['extrinsic_matrix'], dtype=float).reshape(4, 4)
    r_c2w = T[:3, :3]
    t_c2w = T[:3, 3]
    p_cam = r_c2w.T @ (np.asarray(xyz, dtype=float).reshape(3) - t_c2w)
    depth = -float(p_cam[2])
    if depth <= 0.0001:
        return None
    fx, fy = (float(K[0, 0]), float(K[1, 1]))
    cx, cy = (float(K[0, 2]), float(K[1, 2]))
    col = cx + fx * (float(p_cam[0]) / depth)
    row = cy - fy * (float(p_cam[1]) / depth)
    return (float(row), float(col))

def _intersect_ray_plane_z(origin_w, dir_w, z_plane):
    """Intersect a world ray with horizontal plane z = z_plane."""
    dz = float(dir_w[2])
    if abs(dz) < 1e-06:
        return None
    t = (float(z_plane) - float(origin_w[2])) / dz
    if t <= 0.0:
        return None
    return origin_w + t * dir_w

def _intersect_ray_plane_y(origin_w, dir_w, y_plane):
    """Intersect a world ray with vertical plane y = y_plane."""
    dy = float(dir_w[1])
    if abs(dy) < 1e-06:
        return None
    t = (float(y_plane) - float(origin_w[1])) / dy
    if t <= 0.0:
        return None
    return origin_w + t * dir_w

def _query_locate_candidates(robo, prompts, camera='cam_head', min_score=0.2):
    """Try multiple prompts with robo.locate and return the best valid ObjectSight."""
    best = None
    best_rank = (-1, -1.0)
    for prompt in prompts:
        try:
            sight = robo.locate(prompt, camera=camera, min_score=min_score)
        except Exception:
            continue
        if sight is None or not getattr(sight, 'found', False):
            continue
        c_xyz = getattr(sight, 'center_xyz', None)
        if c_xyz is None or len(c_xyz) < 3:
            continue
        views = int(getattr(sight, 'views', 0) or 0)
        score = float(getattr(sight, 'score', 0.0) or 0.0)
        rank = (views, score)
        if rank > best_rank:
            best_rank = rank
            best = sight
            if views >= 2 and score >= 0.45:
                break
    return best

def _refine_cup_rim_from_rgb(robo, cup_center_xy, z_rim, length_m, width_m, long_axis_deg, bottle_x):
    """Estimate the 3D circular opening center of the cup at height z_rim.

    Combines:
      1. Direct detection of the bright circular inner cavity rim in cam_head around
         the projected cup top, back-projected onto plane z = z_rim.
      2. Handle-asymmetry compensation when length_m - width_m > 0.015 m (where the
         located footprint centre is shifted toward the side handle).
    """
    cx_foot, cy_foot = (float(cup_center_xy[0]), float(cup_center_xy[1]))
    sx = float(length_m) if length_m is not None else FALLBACK_CUP_EXTENT_M
    sy = float(width_m) if width_m is not None else FALLBACK_CUP_EXTENT_M
    asym = max(0.0, sx - sy)
    handle_sign = 1.0 if float(bottle_x) >= cx_foot else -1.0
    if asym > 0.015:
        axis_rad = math.radians(float(long_axis_deg or 0.0))
        dx_geom = -handle_sign * 0.5 * asym * abs(math.cos(axis_rad))
        dy_geom = 0.0
    else:
        dx_geom, dy_geom = (0.0, 0.0)
    geom_rim = np.array([cx_foot + dx_geom, cy_foot + dy_geom, float(z_rim)], dtype=float)
    try:
        img = robo.image('cam_head')
        meta = robo.camera_meta('cam_head')
        proj = _world_to_pixel(meta, geom_rim)
        if proj is None or img is None:
            return geom_rim
        r0, c0 = (int(round(proj[0])), int(round(proj[1])))
        h, w = img.shape[:2]
        half_win = 36
        r_min, r_max = (max(0, r0 - half_win), min(h, r0 + half_win))
        c_min, c_max = (max(0, c0 - half_win), min(w, c0 + half_win))
        if r_max - r_min < 10 or c_max - c_min < 10:
            return geom_rim
        crop = img[r_min:r_max, c_min:c_max].astype(float)
        r_ch, g_ch, b_ch = (crop[:, :, 0], crop[:, :, 1], crop[:, :, 2])
        luma = 0.299 * r_ch + 0.587 * g_ch + 0.114 * b_ch
        sat = np.maximum(np.maximum(r_ch, g_ch), b_ch) - np.minimum(np.minimum(r_ch, g_ch), b_ch)
        cavity_mask = (luma > 185.0) & (sat < 45.0)
        num_px = int(np.sum(cavity_mask))
        if 40 <= num_px <= 1800:
            ys, xs = np.nonzero(cavity_mask)
            row_cav = float(r_min) + float(np.mean(ys))
            col_cav = float(c_min) + float(np.mean(xs))
            orig_w, dir_w = _pixel_to_world_ray(meta, row_cav, col_cav)
            hit = _intersect_ray_plane_z(orig_w, dir_w, float(z_rim))
            if hit is not None and math.hypot(float(hit[0] - geom_rim[0]), float(hit[1] - geom_rim[1])) < 0.03:
                blended = 0.65 * hit + 0.35 * geom_rim
                blended[2] = float(z_rim)
                return blended
    except Exception:
        pass
    return geom_rim

def _mask_from_contours(contours_rc, shape=(480, 640)):
    """Fill a segment's outer outlines into a boolean mask."""
    from PIL import Image, ImageDraw
    im = Image.new('L', (int(shape[1]), int(shape[0])), 0)
    draw = ImageDraw.Draw(im)
    for outline in contours_rc or ():
        pts = [(int(c), int(r)) for r, c in outline]
        if len(pts) >= 3:
            draw.polygon(pts, fill=255)
    return np.asarray(im) > 0

def _height_on_top_ray(meta, row, col, xy):
    """Height of the ray through pixel (row, col) where its horizontal travel reaches the distance of ``xy``."""
    origin, direction = _pixel_to_world_ray(meta, row, col)
    horizontal = float(np.linalg.norm(direction[:2]))
    if horizontal < 1e-06:
        return None
    t = float(np.dot(np.asarray(xy, float)[:2] - origin[:2], direction[:2] / horizontal)) / horizontal
    return float(origin[2] + t * direction[2]) if t > 0 else None

def bottle_height_from_head(mask, meta, table_z, center_xy=None):
    """Bottle height above the table from its head-camera mask.

    The ray through the mask's top pixel is read at the bottle's distance from the camera.  With
    ``center_xy`` (a two-view located centre) that distance is the centre's; without it the centre
    is placed from the base: the lowest mask pixel's ray meets the table plane at the near edge of
    the base, and the centre lies one body radius (half the mask width just above the base, at that
    depth) further along the viewing direction.  Returns (height_m, method) or None.
    """
    rows, cols = np.nonzero(np.asarray(mask, bool))
    if len(rows) < 200:
        return None
    top = int(rows.min())
    top_col = float(cols[rows <= top + 1].mean())
    if center_xy is not None:
        z = _height_on_top_ray(meta, top, top_col, center_xy)
        if z is None:
            return None
        return (z - float(table_z), 'top_ray_at_located_centre')
    bottom = int(rows.max())
    bottom_col = float(cols[rows >= bottom - 1].mean())
    band = (rows >= bottom - 18) & (rows <= bottom - 6)
    widths = [cols[rows == r].max() - cols[rows == r].min() + 1 for r in np.unique(rows[band])]
    if not widths:
        return None
    origin, direction = _pixel_to_world_ray(meta, bottom + 0.5, bottom_col)
    base = _intersect_ray_plane_z(origin, direction, float(table_z))
    if base is None:
        return None
    K = np.asarray(meta['intrinsic_matrix'], float).reshape(3, 3)
    T = np.asarray(meta['extrinsic_matrix'], float).reshape(4, 4)
    depth = float(-((base - T[:3, 3]) @ T[:3, :3])[2])
    radius = 0.5 * float(np.median(widths)) * depth / float(K[0, 0])
    away = _unit([base[0] - origin[0], base[1] - origin[1], 0.0])
    center = base[:2] + radius * away[:2]
    z = _height_on_top_ray(meta, top, top_col, center)
    if z is None:
        return None
    return (z - float(table_z), 'top_ray_at_base_centre')

def _located_bottle_height(robo, bottle_sight, z_table_est):
    """Bottle height above the table from the head image (bottle_height_from_head), else FALLBACK_BOTTLE_HEIGHT_M."""
    center = None
    if int(getattr(bottle_sight, 'views', 0) or 0) >= 2 and getattr(bottle_sight, 'center_xyz', None) is not None:
        center = np.asarray(bottle_sight.center_xyz, float)[:2]
    try:
        seg = robo.segment('the bottle', camera='cam_head', min_score=0.5, include_contours=True)
        if getattr(seg, 'found', False) and getattr(seg, 'contours_rc', None):
            image = robo.image('cam_head')
            reading = bottle_height_from_head(_mask_from_contours(seg.contours_rc, np.asarray(image).shape[:2]), robo.camera_meta('cam_head'), z_table_est, center)
            if reading is not None and (0.15, 0.3)[0] <= reading[0] <= (0.15, 0.3)[1]:
                return reading
    except Exception as exc:
        if _is_termination_exc(exc):
            raise
    return (FALLBACK_BOTTLE_HEIGHT_M, 'rgb_fit_2026_11_18_fallback')

def _refine_bottle_xy_from_rgb(robo, bottle_sight, z_table_est, bottle_height):
    center = np.asarray(bottle_sight.center_xyz, float)[:2]
    if int(getattr(bottle_sight, 'views', 0) or 0) >= 2:
        return tuple(center)
    z = float(z_table_est) + float(bottle_height)
    try:
        fit = _fit_upright_mouth(robo.image('cam_head'), robo.camera_meta('cam_head'), center, z)
    except ValueError as error:
        seg = robo.segment('the inside of the bottle mouth', camera='cam_head', min_score=0.5)
        if not seg.found or seg.centroid is None or seg.score is None or (seg.score < 0.5) or (not 50 <= seg.area_px <= 2000):
            raise ValueError('Initial mouth segment uncertain') from error
        origin, direction = _pixel_to_world_ray(robo.camera_meta('cam_head'), *seg.centroid)
        point = _intersect_ray_plane_z(origin, direction, z)
        if point is None or np.linalg.norm(point[:2] - center) > 0.09:
            raise ValueError('Initial mouth projection inconsistent') from error
        fit = {'xy': point[:2].tolist(), 'source': 'SAM opening centroid with upright height prior', 'score': seg.score, 'area_px': seg.area_px, 'centroid': seg.centroid}
        print('INITIAL_MOUTH_SAM_FALLBACK', fit, flush=True)
    print('UPRIGHT_MOUTH_FIT', fit, flush=True)
    return tuple(fit['xy'])

def locate_bottle_and_cup(robo, z_table_default=FALLBACK_SUPPORT_Z):
    """Locate bottle and cup using perception tools and compute calibrated 3D geometry.

    Returns a dict `scene_geom` or None if perception confidence is insufficient.
    """
    bottle_prompts = ('the bottle',)
    cup_prompts = ('the cup', 'the mug')
    bottle_sight = _query_locate_candidates(robo, bottle_prompts, camera='cam_head', min_score=0.2)
    cup_sight = _query_locate_candidates(robo, cup_prompts, camera='cam_head', min_score=0.2)
    if bottle_sight is None or cup_sight is None:
        return None
    b_center = np.asarray(bottle_sight.center_xyz, dtype=float).reshape(-1)[:3]
    c_center = np.asarray(cup_sight.center_xyz, dtype=float).reshape(-1)[:3]
    if math.hypot(float(b_center[0] - c_center[0]), float(b_center[1] - c_center[1])) < 0.05:
        return None
    z_table_candidates = []
    for s in (bottle_sight, cup_sight):
        tz = getattr(s, 'top_z', None)
        hm = getattr(s, 'height_m', None)
        if tz is not None and hm is not None and (float(hm) > 0.02):
            zt = float(tz) - float(hm)
            if 0.74 <= zt <= 0.79:
                z_table_candidates.append(zt)
    z_table_est = round(float(np.mean(z_table_candidates)), 4) if z_table_candidates else float(z_table_default)
    bottle_height, bottle_height_source = _located_bottle_height(robo, bottle_sight, z_table_est)
    x_b, y_b = _refine_bottle_xy_from_rgb(robo, bottle_sight, z_table_est, bottle_height)
    z_b_body = round(z_table_est + 0.275 * bottle_height, 4)
    b_pos0 = np.array([x_b, y_b, z_b_body], dtype=float)
    c_top_z = getattr(cup_sight, 'top_z', None)
    c_views = int(getattr(cup_sight, 'views', 0) or 0)
    if c_top_z is None or not z_table_est + 0.055 <= float(c_top_z) <= z_table_est + 0.12 or c_views < 2:
        if c_top_z is not None and z_table_est + 0.068 <= float(c_top_z) <= z_table_est + 0.105:
            z_rim = float(c_top_z)
        else:
            z_rim = z_table_est + FALLBACK_RIM_HEIGHT_M
    else:
        z_rim = float(c_top_z)
    rim_xyz = _refine_cup_rim_from_rgb(robo, c_center[:2], z_rim, getattr(cup_sight, 'length_m', None), getattr(cup_sight, 'width_m', None), getattr(cup_sight, 'long_axis_deg', None), x_b)
    if float(b_pos0[0]) <= float(rim_xyz[0]):
        work_arm = 'left'
        idle_arm = 'right'
        sign = 1.0
    else:
        work_arm = 'right'
        idle_arm = 'left'
        sign = -1.0
    scene_geom = {'z_table_est': float(z_table_est), 'b_pos_init': b_pos0.copy(), 'c_pos_init': c_center.copy(), 'rim_xyz': rim_xyz.copy(), 'work_arm': work_arm, 'idle_arm': idle_arm, 'sign': float(sign), 'bottle_views': int(getattr(bottle_sight, 'views', 0) or 0), 'bottle_height_m': float(bottle_height), 'bottle_height_source': bottle_height_source, 'cup_views': c_views, 'grasp_z': None, 'grasp_yaw': 0.0, 'tcp_to_mouth_eef': np.array([0.0, 0.0, 0.123], dtype=float), 'tcp_to_bottle_eef': np.array([0.0, 0.0, -0.035], dtype=float), 'r_eef_to_bottle': np.eye(3, dtype=float)}
    return scene_geom

def _detect_held_mouth_rgb(robo, pred_mouth_xyz, y_plane):
    """Detect the dark-red bottle cap/mouth tip in cam_head near pred_mouth_xyz.

    Projects the top/pour-side tip of the dark-red cap ray onto vertical plane y = y_plane.
    Returns (mouth_xyz_rgb, confidence) or (None, 0.0).
    """
    try:
        img = robo.image('cam_head')
        meta = robo.camera_meta('cam_head')
        if img is None or meta is None:
            return (None, 0.0)
        proj = _world_to_pixel(meta, pred_mouth_xyz)
        if proj is None:
            return (None, 0.0)
        r0, c0 = (int(round(proj[0])), int(round(proj[1])))
        h, w = img.shape[:2]
        win = 42
        r_min, r_max = (max(0, r0 - win), min(h, r0 + win))
        c_min, c_max = (max(0, c0 - win), min(w, c0 + win))
        if r_max - r_min < 10 or c_max - c_min < 10:
            return (None, 0.0)
        crop = img[r_min:r_max, c_min:c_max].astype(float)
        r_ch, g_ch, b_ch = (crop[:, :, 0], crop[:, :, 1], crop[:, :, 2])
        maroon_mask = (r_ch > 55.0) & (r_ch < 175.0) & (r_ch > 2.1 * g_ch + 12.0) & (r_ch > 1.9 * b_ch + 12.0) & (g_ch < 55.0) & (b_ch < 60.0)
        cnt = int(np.sum(maroon_mask))
        if cnt < 10 or cnt > 1200:
            return (None, 0.0)
        ys, xs = np.nonzero(maroon_mask)
        row_c = float(r_min) + float(np.mean(ys))
        col_c = float(c_min) + float(np.mean(xs))
        orig_w, dir_w = _pixel_to_world_ray(meta, row_c, col_c)
        hit = _intersect_ray_plane_y(orig_w, dir_w, float(y_plane))
        if hit is None:
            return (None, 0.0)
        dist = float(np.linalg.norm(hit - np.asarray(pred_mouth_xyz, dtype=float)))
        if dist > 0.032:
            return (None, 0.0)
        conf = max(0.0, 1.0 - dist / 0.032)
        return (hit, conf)
    except Exception:
        return (None, 0.0)

def measure_synchronized_mouth(robo, scene_geom, work_arm=None, sign=None):
    """Measure synchronized robot EEF/TCP state and held-bottle 3D mouth transform."""
    if work_arm is None:
        work_arm = scene_geom['work_arm']
    if sign is None:
        sign = float(scene_geom['sign'])
    idle_arm = 'right' if work_arm == 'left' else 'left'
    st = robo.state()
    arm_st = st.left if work_arm == 'left' else st.right
    tcp_pos = np.asarray(arm_st.tcp_pos, dtype=float).reshape(-1)[:3]
    eef_pos = np.asarray(getattr(arm_st, 'eef_pos', tcp_pos), dtype=float).reshape(-1)[:3]
    eef_quat = np.asarray(getattr(arm_st, 'eef_quat', [0.70710678, 0.0, 0.0, 0.70710678]), dtype=float).reshape(-1)[:4]
    r_eef = _quat_to_mat(eef_quat)
    r_eef_to_bottle = np.asarray(scene_geom.get('r_eef_to_bottle', np.eye(3, dtype=float)), dtype=float).reshape(3, 3)
    r_bottle = r_eef @ r_eef_to_bottle
    bottle_axis = _unit(r_bottle @ np.array([0.0, 0.0, 1.0], dtype=float))
    v_tcp_to_mouth_eef = np.asarray(scene_geom.get('tcp_to_mouth_eef', [0.0, 0.0, 0.123]), dtype=float).reshape(3)
    v_tcp_to_bottle_eef = np.asarray(scene_geom.get('tcp_to_bottle_eef', [0.0, 0.0, -0.035]), dtype=float).reshape(3)
    mouth_pos_kin = tcp_pos + r_eef @ v_tcp_to_mouth_eef
    b_pos_kin = tcp_pos + r_eef @ v_tcp_to_bottle_eef
    rim_xyz = np.asarray(scene_geom['rim_xyz'], dtype=float).reshape(3)
    if scene_geom.get('multiview_mouth_calibrated'):
        mouth_rgb, conf_rgb = (None, 0.0)
    else:
        mouth_rgb, conf_rgb = _detect_held_mouth_rgb(robo, mouth_pos_kin, y_plane=float(rim_xyz[1]))
    if mouth_rgb is not None and conf_rgb > 0.35:
        mouth_pos = 0.8 * mouth_pos_kin + 0.2 * mouth_rgb
    else:
        mouth_pos = mouth_pos_kin
    r_spout = SPOUT_OUTER_RADIUS_M
    u_lip = _pouring_lip_unit_vec(r_bottle, sign)
    lip_pos = mouth_pos + r_spout * u_lip
    tcp_to_mouth_world = mouth_pos - tcp_pos
    tcp_to_mouth_eef = r_eef.T @ tcp_to_mouth_world
    lever_length_m = float(np.linalg.norm(tcp_to_mouth_world))
    return {'work_arm': work_arm, 'idle_arm': idle_arm, 'sign': float(sign), 'tcp_pos': tcp_pos, 'eef_pos': eef_pos, 'eef_quat': eef_quat, 'r_eef': r_eef, 'b_pos': b_pos_kin, 'r_bottle': r_bottle, 'bottle_axis': bottle_axis, 'rim_xyz': rim_xyz.copy(), 'mouth_pos': mouth_pos, 'lip_pos': lip_pos, 'u_lip': u_lip, 'r_spout': r_spout, 'tcp_to_mouth_world': tcp_to_mouth_world, 'tcp_to_mouth_eef': tcp_to_mouth_eef, 'tcp_to_bottle_eef': v_tcp_to_bottle_eef, 'r_eef_to_bottle': r_eef_to_bottle, 'lever_length_m': lever_length_m, 'rgb_mouth_conf': round(float(conf_rgb), 4)}

def compute_synchronized_tcp_target(sync_state, target_mouth_xyz, *, pitch=0.0, yaw=0.0, roll=0.0, residual_corr_xyz=None):
    """Compute TCP [x, y, z] that places the bottle mouth center at target_mouth_xyz."""
    target_mouth = np.asarray(target_mouth_xyz, dtype=float).reshape(-1)[:3]
    r_eef_target = _rpy_to_eef_mat(pitch_deg=pitch, yaw_deg=yaw, roll_deg=roll)
    v_eef = np.asarray(sync_state['tcp_to_mouth_eef'], dtype=float).reshape(-1)[:3]
    norm_v = float(np.linalg.norm(v_eef))
    if not np.all(np.isfinite(v_eef)) or norm_v < 0.05 or norm_v > 0.25:
        v_eef = np.array([0.0, 0.0, 0.123], dtype=float)
    delta_mouth_pred = r_eef_target @ v_eef
    corr = np.zeros(3, dtype=float)
    if residual_corr_xyz is not None:
        corr = np.clip(np.asarray(residual_corr_xyz, dtype=float).reshape(-1)[:3], -0.02, 0.02)
    tcp_cmd = target_mouth + corr - delta_mouth_pred
    return [round(float(tcp_cmd[0]), 4), round(float(tcp_cmd[1]), 4), round(float(tcp_cmd[2]), 4)]

def compute_mouth_residuals(sync_state, desired_mouth_xyz):
    """Compute diagnostic residuals between desired mouth pose, achieved mouth pose, and cup cavity."""
    des = np.asarray(desired_mouth_xyz, dtype=float).reshape(-1)[:3]
    ach_mouth = np.asarray(sync_state['mouth_pos'], dtype=float).reshape(-1)[:3]
    ach_lip = np.asarray(sync_state['lip_pos'], dtype=float).reshape(-1)[:3]
    rim = np.asarray(sync_state['rim_xyz'], dtype=float).reshape(-1)[:3]
    err_xyz = des - ach_mouth
    err_xy = float(math.hypot(float(err_xyz[0]), float(err_xyz[1])))
    err_3d = float(np.linalg.norm(err_xyz))
    mouth_to_cavity_xy = float(math.hypot(float(ach_mouth[0] - rim[0]), float(ach_mouth[1] - rim[1])))
    lip_to_cavity_xy = float(math.hypot(float(ach_lip[0] - rim[0]), float(ach_lip[1] - rim[1])))
    lip_clearance_z = float(ach_lip[2] - rim[2])
    mouth_clearance_z = float(ach_mouth[2] - rim[2])
    geometry_ok = mouth_to_cavity_xy <= 0.028 and abs(float(ach_mouth[1] - rim[1])) <= 0.008 and (lip_clearance_z >= 0.012)
    return {'desired_mouth_xyz': [round(float(x), 5) for x in des], 'achieved_mouth_xyz': [round(float(x), 5) for x in ach_mouth], 'achieved_lip_xyz': [round(float(x), 5) for x in ach_lip], 'rim_xyz': [round(float(x), 5) for x in rim], 'mouth_error_xyz': [round(float(x), 5) for x in err_xyz], 'mouth_error_xy_m': round(err_xy, 5), 'mouth_error_3d_m': round(err_3d, 5), 'mouth_to_cavity_xy_m': round(mouth_to_cavity_xy, 5), 'lip_to_cavity_xy_m': round(lip_to_cavity_xy, 5), 'lip_clearance_z_m': round(lip_clearance_z, 5), 'mouth_clearance_z_m': round(mouth_clearance_z, 5), 'lever_length_m': round(float(sync_state['lever_length_m']), 5), 'geometry_ok': bool(geometry_ok)}

def verify_grasp_and_lift_observable(robo, work_arm, g_close, z_grasp, z_lift, pre_head_img=None):
    """Verify bottle retention after lift using gripper proprioception and wrist/head RGB."""
    holding_ok = bool(getattr(g_close, 'holding', False))
    opening = float(getattr(g_close, 'opening', 0.0) or 0.0)
    width_m = float(getattr(g_close, 'width_m', 0.0) or 0.0)
    st = robo.state()
    arm_st = st.left if work_arm == 'left' else st.right
    gripper_now = float(getattr(arm_st, 'gripper', opening))
    tcp_now = np.asarray(arm_st.tcp_pos, dtype=float).reshape(-1)[:3]
    grip_valid = holding_ok and 0.25 <= opening <= 0.9 and (0.25 <= gripper_now <= 0.9)
    if width_m > 0.0 and (not 0.045 <= width_m <= 0.105):
        grip_valid = False
    wrist_cam = 'cam_left_wrist' if work_arm == 'left' else 'cam_right_wrist'
    wrist_bottle_ratio = 0.0
    try:
        w_img = robo.image(wrist_cam)
        if w_img is not None:
            h, w = w_img.shape[:2]
            center_crop = w_img[int(0.2 * h):int(0.8 * h), int(0.25 * w):int(0.75 * w)].astype(float)
            r_c, g_c, b_c = (center_crop[:, :, 0], center_crop[:, :, 1], center_crop[:, :, 2])
            neutral_mask = (np.abs(r_c - b_c) < 35.0) & (g_c > 45.0)
            wrist_bottle_ratio = float(np.mean(neutral_mask))
    except Exception:
        wrist_bottle_ratio = 0.5
    head_changed = True
    if pre_head_img is not None:
        try:
            post_head_img = robo.image('cam_head')
            if post_head_img is not None and post_head_img.shape == pre_head_img.shape:
                diff = float(np.mean(np.abs(post_head_img.astype(float) - pre_head_img.astype(float))))
                head_changed = diff > 1.5
        except Exception:
            head_changed = True
    lifted_tcp_dz = float(tcp_now[2]) - float(z_grasp)
    ok = grip_valid and lifted_tcp_dz > 0.025 and (wrist_bottle_ratio > 0.18) and head_changed
    return (ok, {'holding_ok': bool(grip_valid), 'opening': round(opening, 4), 'gripper_now': round(gripper_now, 4), 'width_m': round(width_m, 4), 'lifted_tcp_dz_m': round(lifted_tcp_dz, 5), 'wrist_bottle_ratio': round(wrist_bottle_ratio, 4), 'head_changed': bool(head_changed)})

def grasp_and_lift_bottle(robo, scene_geom, work_arm=None):
    """Grasp the lower cylindrical bottle body and verify lift from observable evidence."""
    if work_arm is None:
        work_arm = scene_geom['work_arm']
    for attempt in range(2):
        if not _episode_active(robo):
            return False
        if attempt > 0:
            refreshed = locate_bottle_and_cup(robo, z_table_default=scene_geom['z_table_est'])
            if refreshed is not None:
                scene_geom['b_pos_init'] = refreshed['b_pos_init']
        b_pos_cur = np.asarray(scene_geom['b_pos_init'], dtype=float).reshape(3)
        x_b = round(float(b_pos_cur[0]), 4)
        y_b = round(float(b_pos_cur[1]), 4)
        z_b = float(b_pos_cur[2])
        z_grasp_candidates = [round(z_b + 0.035, 4), round(z_b + 0.025, 4), round(z_b + 0.015, 4)]
        if attempt == 1:
            z_grasp_candidates = [round(z_b + 0.028, 4), round(z_b + 0.02, 4), round(z_b + 0.035, 4)]
        selected = None
        print('GRASP_INPUT', scene_geom, flush=True)
        for pitch_candidate in [0.0, 15.0]:
            for zg in z_grasp_candidates:
                for yaw_candidate in [0.0, 30.0, -30.0]:
                    ok_g, preview = _preview_ok(robo, [x_b, y_b, zg], arm=work_arm, pitch=pitch_candidate, yaw=yaw_candidate, path='auto')
                    print('GRASP_PREVIEW', dict(xyz=[x_b, y_b, zg], pitch=pitch_candidate, yaw=yaw_candidate, ok=ok_g, preview=preview), flush=True)
                    if ok_g:
                        selected = (zg, yaw_candidate, pitch_candidate)
                        break
                if selected is not None:
                    break
            if selected is not None:
                break
        if selected is None:
            return False
        z_grasp, yaw_grasp, pitch_grasp = selected
        top_approach_z = None
        for z_top in [round(z_b + 0.195, 4), round(z_b + 0.18, 4), round(z_b + 0.17, 4)]:
            ok_top, _ = _preview_ok(robo, [x_b, y_b, z_top], arm=work_arm, pitch=pitch_grasp, yaw=yaw_grasp, path='auto')
            if ok_top:
                top_approach_z = z_top
                break
        if top_approach_z is not None:
            m_pre = _safe_move(robo, [x_b, y_b, top_approach_z], arm=work_arm, gripper=robo.OPEN, pitch=pitch_grasp, yaw=yaw_grasp, roll=0.0, prefer_path='auto')
        else:
            y_pre = round(y_b - 0.095, 4)
            m_pre = _safe_move(robo, [x_b, y_pre, z_grasp], arm=work_arm, gripper=robo.OPEN, pitch=pitch_grasp, yaw=yaw_grasp, roll=0.0, prefer_path='auto')
        if m_pre is None or getattr(m_pre, 'truncated', False):
            return False
        m_down = _safe_move(robo, [x_b, y_b, z_grasp], arm=work_arm, gripper=robo.OPEN, pitch=pitch_grasp, yaw=yaw_grasp, roll=0.0, prefer_path='line')
        if m_down is None or getattr(m_down, 'truncated', False):
            return False
        try:
            pre_head_img = robo.image('cam_head')
        except Exception:
            pre_head_img = None
        g_close = _safe_grip(robo, work_arm, robo.CLOSE)
        if g_close is None or getattr(g_close, 'truncated', False):
            return False
        st_grasp = robo.state()
        arm_grasp = st_grasp.left if work_arm == 'left' else st_grasp.right
        tcp_grasp = np.asarray(arm_grasp.tcp_pos, dtype=float).reshape(3)
        r_eef_grasp = _quat_to_mat(getattr(arm_grasp, 'eef_quat', [0.70710678, 0.0, 0.0, 0.70710678]))
        mouth_z = float(scene_geom['z_table_est']) + float(scene_geom.get('bottle_height_m', FALLBACK_BOTTLE_HEIGHT_M))
        mouth_world_grasp = np.array([x_b, y_b, mouth_z], dtype=float)
        bottle_world_grasp = np.array([x_b, y_b, z_b], dtype=float)
        scene_geom['grasp_z'] = float(z_grasp)
        scene_geom['grasp_yaw'] = float(yaw_grasp)
        scene_geom['tcp_to_mouth_eef'] = r_eef_grasp.T @ (mouth_world_grasp - tcp_grasp)
        scene_geom['tcp_to_bottle_eef'] = r_eef_grasp.T @ (bottle_world_grasp - tcp_grasp)
        scene_geom['r_eef_to_bottle'] = r_eef_grasp.T @ np.eye(3, dtype=float)
        z_lift = round(float(mouth_z), 4)
        m_lift = _safe_move(robo, [x_b, y_b, z_lift], arm=work_arm, gripper=robo.CLOSE, pitch=pitch_grasp, yaw=yaw_grasp, roll=0.0, prefer_path='line')
        if m_lift is None or getattr(m_lift, 'truncated', False):
            return False
        ok_lift, lift_diag = verify_grasp_and_lift_observable(robo, work_arm, g_close, z_grasp, z_lift, pre_head_img=pre_head_img)
        sync_lift = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm)
        lift_diag['attempt'] = attempt + 1
        lift_diag['lever_length_m'] = round(float(sync_lift['lever_length_m']), 5)
        LAST_DIAGNOSTICS['pickup'] = lift_diag
        if ok_lift:
            return True
        _safe_grip(robo, work_arm, robo.OPEN)
    return False

def move_mouth_to_stage(robo, scene_geom, *, work_arm, sign, roll_mag, x_mouth_off, z_mouth_off, verify_and_correct=False, stage_label='stage'):
    """Move the held bottle using the synchronized 3D mouth transform and record residuals."""
    sync_pre = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
    rim_xyz = sync_pre['rim_xyz']
    rad = math.radians(abs(float(roll_mag)))
    min_mouth_z_off = 0.019 + sync_pre['r_spout'] * math.sin(rad)
    eff_z_off = max(float(z_mouth_off), min_mouth_z_off)
    desired_mouth = np.array([float(rim_xyz[0]) + float(sign) * float(x_mouth_off), float(rim_xyz[1]), float(rim_xyz[2]) + eff_z_off], dtype=float)
    tcp_cmd = compute_synchronized_tcp_target(sync_pre, desired_mouth, pitch=0.0, yaw=0.0, roll=float(sign) * float(roll_mag))
    m = _safe_move(robo, tcp_cmd, arm=work_arm, gripper=robo.CLOSE, pitch=0.0, yaw=0.0, roll=float(sign) * float(roll_mag), prefer_path='line')
    if m is None or getattr(m, 'truncated', False):
        return (False, None)
    sync_post = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
    res_diag = compute_mouth_residuals(sync_post, desired_mouth)
    res_diag['stage'] = stage_label
    res_diag['roll_deg'] = round(float(sign) * float(roll_mag), 2)
    res_diag['corrected'] = False
    if verify_and_correct and _episode_active(robo):
        need_corr = res_diag['mouth_error_xy_m'] > 0.0045 or abs(float(res_diag['mouth_error_xyz'][2])) > 0.0065 or (not res_diag['geometry_ok'])
        if need_corr:
            rim_now = sync_post['rim_xyz']
            desired_mouth_now = np.array([float(rim_now[0]) + float(sign) * float(x_mouth_off), float(rim_now[1]), float(rim_now[2]) + eff_z_off], dtype=float)
            tcp_corr = compute_synchronized_tcp_target(sync_post, desired_mouth_now, pitch=0.0, yaw=0.0, roll=float(sign) * float(roll_mag))
            m_corr = _safe_move(robo, tcp_corr, arm=work_arm, gripper=robo.CLOSE, pitch=0.0, yaw=0.0, roll=float(sign) * float(roll_mag), prefer_path='line')
            if m_corr is None or getattr(m_corr, 'truncated', False):
                return (False, res_diag)
            sync_corr = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
            res_diag = compute_mouth_residuals(sync_corr, desired_mouth_now)
            res_diag['stage'] = stage_label
            res_diag['roll_deg'] = round(float(sign) * float(roll_mag), 2)
            res_diag['corrected'] = True
    LAST_DIAGNOSTICS.setdefault('early_pour_stages', []).append(res_diag)
    if verify_and_correct and (not res_diag['geometry_ok']):
        return (False, res_diag)
    return (True, res_diag)

def run_early_pour_phase(robo, scene_geom, work_arm=None, idle_arm=None, sign=None):
    """Execute synchronized pre-pour alignment and initial pouring tilt (60 -> 124 deg)."""
    sync0 = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
    work_arm = sync0['work_arm']
    idle_arm = sync0['idle_arm'] if idle_arm is None else idle_arm
    sign = sync0['sign']
    LAST_DIAGNOSTICS['early_pour_stages'] = []
    for roll in range(60, 130, 10):
        ok, _ = move_mouth_to_stage(robo, scene_geom, work_arm=work_arm, sign=sign, roll_mag=float(roll), x_mouth_off=0.0, z_mouth_off=0.0, verify_and_correct=True, stage_label=f'roll_{roll}')
        if not ok:
            return False
        if not _episode_active(robo):
            return False
    return True

def _observable_needs_recovery(robo, scene_geom):
    """Check cam_head RGB around the cup cavity to see if pink/red liquid is absent."""
    try:
        img = robo.image('cam_head')
        meta = robo.camera_meta('cam_head')
        rim_xyz = scene_geom['rim_xyz']
        proj = _world_to_pixel(meta, rim_xyz)
        if proj is None or img is None:
            return False
        r0, c0 = (int(round(proj[0])), int(round(proj[1])))
        h, w = img.shape[:2]
        win = 18
        r_min, r_max = (max(0, r0 - win), min(h, r0 + win))
        c_min, c_max = (max(0, c0 - win), min(w, c0 + win))
        crop = img[r_min:r_max, c_min:c_max].astype(float)
        r_ch, g_ch, b_ch = (crop[:, :, 0], crop[:, :, 1], crop[:, :, 2])
        liquid_mask = (r_ch > 180.0) & (r_ch - g_ch > 35.0) & (g_ch > 55.0) & (b_ch > 55.0)
        liquid_px = int(np.sum(liquid_mask))
        LAST_DIAGNOSTICS['post_pour_liquid_px'] = liquid_px
        return liquid_px < 15
    except Exception:
        return False

def run_drain_and_untilt_phase(robo, scene_geom, work_arm=None, idle_arm=None, sign=None):
    """Execute high-angle draining (134 -> 154 deg), smooth untilt to upright, and optional recovery."""
    if work_arm is None:
        work_arm = scene_geom['work_arm']
    if idle_arm is None:
        idle_arm = scene_geom['idle_arm']
    if sign is None:
        sign = float(scene_geom['sign'])
    z_b_init = float(scene_geom['b_pos_init'][2])
    for roll in (140, 150, 90, 45):
        ok, _ = move_mouth_to_stage(robo, scene_geom, work_arm=work_arm, sign=sign, roll_mag=float(roll), x_mouth_off=0.0, z_mouth_off=0.0, verify_and_correct=True, stage_label=f'roll_{roll}')
        if not ok:
            return False
        if not _episode_active(robo):
            return False
    sync_before_upright = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
    tcp_now = sync_before_upright['tcp_pos']
    upright_target = [float(tcp_now[0]), float(tcp_now[1]), z_b_init]
    m_u0 = _safe_move(robo, upright_target, arm=work_arm, gripper=robo.CLOSE, pitch=0.0, yaw=0.0, roll=0.0, prefer_path='line')
    if m_u0 is None or getattr(m_u0, 'truncated', False) or (not _episode_active(robo)):
        return False
    sync_u0 = measure_synchronized_mouth(robo, scene_geom, work_arm=work_arm, sign=sign)
    bottle_z_cos = float(sync_u0['bottle_axis'][2])
    if bottle_z_cos <= math.cos(math.radians(20.0)):
        tcp_u0 = sync_u0['tcp_pos']
        m_fix = _safe_move(robo, [float(tcp_u0[0]), float(tcp_u0[1]), z_b_init], arm=work_arm, gripper=robo.CLOSE, pitch=0.0, yaw=0.0, roll=0.0, prefer_path='auto')
        if m_fix is None or getattr(m_fix, 'truncated', False) or (not _episode_active(robo)):
            return False
    if _episode_active(robo) and _observable_needs_recovery(robo, scene_geom):
        for label, r_mag, x_off, z_off in [('rec_90', 90.0, -0.018, 0.045), ('rec_154', 154.0, -0.008, 0.035)]:
            ok, _ = move_mouth_to_stage(robo, scene_geom, work_arm=work_arm, sign=sign, roll_mag=r_mag, x_mouth_off=x_off, z_mouth_off=z_off, verify_and_correct=False, stage_label=label)
            if not ok:
                return False
        _dwell(robo, idle_arm, 14)
        for label, r_mag, x_off, z_off in untilt_stages:
            ok, _ = move_mouth_to_stage(robo, scene_geom, work_arm=work_arm, sign=sign, roll_mag=r_mag, x_mouth_off=x_off, z_mouth_off=z_off, verify_and_correct=False, stage_label=f'rec_{label}')
            if not ok:
                return False
        _safe_move(robo, upright_target, arm=work_arm, gripper=robo.CLOSE, pitch=0.0, yaw=0.0, roll=0.0, prefer_path='line')
    return True

def _cup_camera_unit(vec):
    v = np.asarray(vec, dtype=float).reshape(-1)
    norm = float(np.linalg.norm(v))
    if norm < 1e-09:
        return np.zeros_like(v)
    return v / norm

def _cup_camera_rotation(quat_wxyz):
    """Convert a wxyz quaternion to a 3x3 rotation matrix."""
    q = np.asarray(quat_wxyz, dtype=float).reshape(4)
    norm = float(np.linalg.norm(q))
    if norm < 1e-09:
        return np.eye(3, dtype=float)
    w, x, y, z = q / norm
    return np.array([[1.0 - 2.0 * (y * y + z * z), 2.0 * (x * y - z * w), 2.0 * (x * z + y * w)], [2.0 * (x * y + z * w), 1.0 - 2.0 * (x * x + z * z), 2.0 * (y * z - x * w)], [2.0 * (x * z - y * w), 2.0 * (y * z + x * w), 1.0 - 2.0 * (x * x + y * y)]], dtype=float)

def _cup_camera_angles(rot_mat):
    """Convert a 3x3 end-effector rotation matrix to this library's pitch, yaw, roll (degrees)."""
    r = np.asarray(rot_mat, dtype=float).reshape(3, 3)
    pitch = math.degrees(math.asin(float(np.clip(-r[2, 0], -1.0, 1.0))))
    if math.hypot(float(r[0, 0]), float(r[1, 0])) < 1e-08:
        yaw = math.degrees(math.atan2(float(-r[1, 1]), float(-r[0, 1])))
        roll = 0.0
    else:
        yaw = math.degrees(math.atan2(float(r[1, 0]), float(r[0, 0]))) - 90.0
        roll = math.degrees(math.atan2(float(r[2, 1]), float(r[2, 2])))
    return {'pitch': float(pitch), 'yaw': float((yaw + 180.0) % 360.0 - 180.0), 'roll': float((roll + 180.0) % 360.0 - 180.0)}

def _cup_camera_pose(arm_state, camera_meta, target, center):
    target = np.asarray(target, float)
    center = np.asarray(center, float)
    camera = np.asarray(camera_meta['extrinsic_matrix'], float)
    eef_rotation = _cup_camera_rotation(arm_state.eef_quat)
    camera_in_eef = eef_rotation.T @ camera[:3, :3]
    camera_offset = eef_rotation.T @ (camera[:3, 3] - np.asarray(arm_state.eef_pos))
    tcp_offset = eef_rotation.T @ (np.asarray(arm_state.tcp_pos) - np.asarray(arm_state.eef_pos))
    z = _cup_camera_unit(center - target)
    x = _cup_camera_unit(np.cross(np.array([0.0, 0.0, 1.0]), z))
    y = np.cross(z, x)
    desired_eef = np.column_stack((x, y, z)) @ camera_in_eef.T
    eef_position = center - desired_eef @ camera_offset
    return {'xyz': (eef_position + desired_eef @ tcp_offset).tolist(), **_cup_camera_angles(desired_eef)}
import numpy as np
from scipy.ndimage import label, binary_fill_holes, binary_erosion
from scipy.optimize import least_squares

def fit_rim(images, metas):
    views = []
    for image, meta in zip(images, metas):
        a = np.asarray(image, float)
        mask = (a.min(2) > 205) & (np.ptp(a, axis=2) < 22)
        yy, xx = np.indices(mask.shape)
        mask &= (xx > 160) & (xx < 480) & (yy > 80) & (yy < 420)
        ll, n = label(mask)
        if n == 0:
            raise RuntimeError('No bright neutral rim')
        sizes = np.bincount(ll.ravel())
        sizes[0] = 0
        ring = ll == int(np.argmax(sizes))
        filled = binary_fill_holes(ring)
        if ring.sum() < 400:
            raise RuntimeError('No visible bright cup boundary')
        rows, cols = np.nonzero(ring)
        cutoff = rows.min() + 0.28 * (rows.max() - rows.min())
        arc = []
        for col in np.unique(cols):
            row = np.min(rows[cols == col])
            if row <= cutoff:
                arc.append([row, col])
        rc = np.asarray(arc)[::2]
        if len(rc) < 25:
            raise RuntimeError('Insufficient upper rim arc')
        views.append((rc[:, ::-1].astype(float), np.asarray(meta['intrinsic_matrix']), np.asarray(meta['extrinsic_matrix'])))
    points, K, T = views[-1]
    pixel = points.mean(0)
    ray = T[:3, :3] @ (np.linalg.solve(K, [pixel[0], pixel[1], 1.0]) * [1, -1, -1])
    if abs(ray[2]) < 0.1:
        raise RuntimeError('Grazing camera')
    initial = T[:3, 3] + ray * ((0.85 - T[2, 3]) / ray[2])
    theta = np.linspace(0, 2 * np.pi, 240, endpoint=False)
    circle = np.column_stack([np.cos(theta), np.sin(theta), np.zeros(len(theta))])

    def residual(p):
        xyz = p[:3] + circle * p[3]
        result = []
        for points, K, T in views:
            q = (xyz - T[:3, 3]) @ T[:3, :3]
            depth = -q[:, 2]
            pixels = np.column_stack([K[0, 2] + K[0, 0] * q[:, 0] / depth, K[1, 2] - K[1, 1] * q[:, 1] / depth])
            v = np.roll(pixels, -1, axis=0) - pixels
            f = np.clip(np.sum((points[:, None] - pixels) * v, axis=2) / np.sum(v * v, axis=1), 0, 1)
            near = pixels + f[:, :, None] * v
            result.extend(np.sqrt(np.min(np.sum((points[:, None] - near) ** 2, axis=2), axis=1) + 1e-10))
        return np.asarray(result)
    fit = least_squares(residual, [initial[0], initial[1], 0.85, 0.035], bounds=([initial[0] - 0.1, initial[1] - 0.1, 0.79, 0.015], [initial[0] + 0.1, initial[1] + 0.1, 0.93, 0.065]), loss='soft_l1', max_nfev=160, x_scale='jac')
    error = float(np.median(residual(fit.x)))
    if not fit.success or error > 1.5:
        raise RuntimeError('Rim fit inconsistent')
    return {'rim_xyz': fit.x[:3].tolist(), 'radius': float(fit.x[3]), 'median_pixel_residual': error, 'nfev': int(fit.nfev)}

def inspect_cup_rim(robo):
    geom = locate_bottle_and_cup(robo)
    target = np.asarray(geom['rim_xyz'], float)
    if not np.all(np.isfinite(target)) or not (-0.35 < target[0] < 0.35 and -0.3 < target[1] < 0.15 and (0.79 < target[2] < 0.92)):
        raise RuntimeError('Coarse cup target outside inspection domain')
    arm = geom['idle_arm']
    camera = 'cam_' + arm + '_wrist'
    count = 0
    images = []
    metas = []
    offsets = ([0.0, -0.1, 0.22], [0.0, -0.045, 0.22]) if geom['work_arm'] == 'left' else ([0.0, -0.1, 0.22], [0.0, -0.025, 0.22])
    offsets = list(offsets) + [[0.0, -0.045, 0.22], [0.0, -0.06, 0.22], [-0.04, -0.045, 0.22], [0.04, -0.045, 0.22]]
    for offset in offsets:
        if count == 2:
            break
        if count == 0:
            home = robo.home(arm)
            if not getattr(home, 'reached', False):
                raise RuntimeError('Inspection home failed')
        pose = _cup_camera_pose(robo.state().arm(arm), robo.camera_meta(camera), target, target + np.asarray(offset))
        if not 0.93 < pose['xyz'][2] < 1.2:
            print({'rejected_height': pose})
            continue
        preview = robo.preview_move(pose['xyz'], arm=arm, pitch=pose['pitch'], yaw=pose['yaw'], roll=pose['roll'], path='line')
        if not isinstance(preview, dict) or not preview.get('reachable') or preview.get('ik_error') or preview.get('note'):
            print({'rejected_preview': str(preview), 'pose': pose})
            continue
        reply = robo.move_to(pose['xyz'], arm=arm, pitch=pose['pitch'], yaw=pose['yaw'], roll=pose['roll'], gripper=robo.OPEN, path='line')
        if not getattr(reply, 'reached', False) or getattr(reply, 'blocked', False):
            raise RuntimeError('Camera motion failed')
        images.append(robo.image(camera))
        metas.append(robo.camera_meta(camera))
        print({'cup_inspection_view': count, 'camera': camera, 'coarse_target': target.tolist(), 'calibration': robo.camera_meta(camera), 'reply': str(reply)})
        count += 1
    if count != 2:
        raise RuntimeError('Two calibrated cup views required')
    measured = fit_rim(images, metas)
    geom['rim_xyz'] = np.asarray(measured['rim_xyz'])
    print('RIM_FIT', measured, flush=True)
    reply = robo.home('both')
    if not getattr(reply, 'reached', False):
        raise RuntimeError('Post-inspection home failed')
    return geom

def inspect_held_mouth_multiview(robo, work_arm='right'):
    st = robo.state()
    work = st.arm(work_arm)
    observer = 'left' if work_arm == 'right' else 'right'
    target = np.asarray(work.tcp_pos) + _quat_to_mat(work.eef_quat) @ np.array([0.0, 0.0, 0.123])
    print('MOUTH_CAMERA_TARGET', target.tolist(), flush=True)
    views = 0
    images = []
    metas = []
    sam_records = []
    for offset in [[-0.14, -0.05, 0.1], [-0.1, -0.12, 0.1]]:
        arm = observer
        camera = 'cam_' + observer + '_wrist'
        offset = np.asarray(offset, float).copy()
        if work_arm == 'left':
            offset[0] *= -1
        if views == 0:
            home = robo.home(arm)
            if not getattr(home, 'reached', False):
                raise RuntimeError('Observer home failed')
        center = target + np.asarray(offset)
        horizontal = np.array([offset[0], offset[1], 0.0])
        horizontal /= np.linalg.norm(horizontal)
        aim = target + 0.025 * horizontal
        pose = _cup_camera_pose(robo.state().arm(observer), robo.camera_meta(camera), aim, center)
        if pose['xyz'][2] < target[2] + 0.025:
            raise RuntimeError('Observer clearance too low')
        preview = robo.preview_move(pose['xyz'], arm=arm, pitch=pose['pitch'], yaw=pose['yaw'], roll=pose['roll'], path='line')
        print('MOUTH_CAMERA_PREVIEW', pose, preview, flush=True)
        if not preview.get('reachable') or preview.get('ik_error') or preview.get('note'):
            continue
        path_points = np.asarray(preview.get('tcp_waypoints', []), float)
        if views > 0 and (len(path_points) == 0 or path_points[:, 2].min() < target[2] + 0.025):
            raise RuntimeError('Observer path below mouth clearance')
        move = robo.move_to(pose['xyz'], arm=arm, pitch=pose['pitch'], yaw=pose['yaw'], roll=pose['roll'], gripper=robo.CLOSE, path='line')
        if not getattr(move, 'reached', False) or getattr(move, 'blocked', False):
            raise RuntimeError('Observer motion failed')
        images.append(robo.image(camera))
        metas.append(robo.camera_meta(camera))
        if work_arm == 'left':
            seg = robo.segment('the inside of the bottle mouth', camera=camera, min_score=0.5)
            sam_records.append(dict(found=bool(getattr(seg, 'found', False)), score=float(getattr(seg, 'score', 0) or 0), area_px=int(getattr(seg, 'area_px', 0)), centroid=getattr(seg, 'centroid', None)))
            print('MOUTH_SAM', sam_records[-1], flush=True)
        print('MOUTH_CAMERA_VIEW', views, {'camera': camera, 'meta': robo.camera_meta(camera), 'reply': str(move)}, flush=True)
        views += 1
    if len(images) != 2:
        raise RuntimeError('Two mouth views required')
    if work_arm == 'left':
        try:
            result = _infer_sam_mouth(sam_records, metas)
        except ValueError as exc:
            print('MOUTH_SEGMENT_FALLBACK', str(exc), flush=True)
            result = infer(images, metas)
    else:
        result = infer(images, metas)
    if len(result['triangulated']) == 1 and np.linalg.norm(np.asarray(result['triangulated'][0]['xyz']) - target) > 0.08:
        result['abstained'] = True
    print('MOUTH_MULTIVIEW ' + json.dumps(result), flush=True)
    return {'camera_only': True, 'views': views, 'mouth_observed': not result['abstained'], 'geometry': result, 'task_success_claim': False}

def _ray(meta, pixel):
    k = np.asarray(meta['intrinsic_matrix'], float)
    t = np.asarray(meta['extrinsic_matrix'], float)
    p = np.asarray(pixel, float)
    shape = meta['shape']
    if k.shape != (3, 3) or t.shape != (4, 4) or p.shape != (2,) or (not all((np.isfinite(x).all() for x in (k, t, p)))):
        raise ValueError('Invalid calibration/pixel')
    if not (0 <= p[0] < shape[0] and 0 <= p[1] < shape[1]) or min(k[0, 0], k[1, 1]) <= 0:
        raise ValueError('Pixel/focal length invalid')
    if not np.allclose(t[:3, :3].T @ t[:3, :3], np.eye(3), atol=1e-05):
        raise ValueError('Nonrigid extrinsics')
    ray = np.linalg.solve(k, [p[1], p[0], 1.0]) * [1, -1, -1]
    return (t[:3, 3], _unit(t[:3, :3] @ ray))

def triangulate(meta_a, pixel_a, meta_b, pixel_b, *, min_parallax_degrees=10, max_ray_gap_m=0.005):
    if not 0 < min_parallax_degrees < 90 or not np.isfinite(max_ray_gap_m) or max_ray_gap_m < 0:
        raise ValueError('Invalid triangulation thresholds')
    a, u = _ray(meta_a, pixel_a)
    b, v = _ray(meta_b, pixel_b)
    parallax = float(np.degrees(np.arccos(np.clip(abs(u @ v), 0, 1))))
    if parallax < min_parallax_degrees:
        raise ValueError('Acquire a better separated view')
    distances, _, rank, _ = np.linalg.lstsq(np.column_stack((u, -v)), b - a, rcond=None)
    if rank != 2 or np.any(distances <= 0):
        raise ValueError('Invalid feature correspondence')
    pa = a + distances[0] * u
    pb = b + distances[1] * v
    gap = float(np.linalg.norm(pa - pb))
    if gap > max_ray_gap_m:
        raise ValueError('Feature rays disagree')
    return dict(xyz=(pa + pb) / 2, ray_gap_m=gap, parallax_degrees=parallax)

def _interior_candidates_kernel(rgb, kernel):
    from scipy import ndimage as nd
    a = np.asarray(rgb, dtype=float)
    r, g, b = a.transpose(2, 0, 1)
    mask = nd.binary_opening((g > b) & (g > 0.6 * r) & (r > 10), structure=np.ones((kernel, kernel)))
    red = (r > 15) & (r > g * 1.5) & (r > b * 1.2) & (b > g * 1.1)
    labels, count = nd.label(mask)
    candidates = []
    for i in range(1, count + 1):
        points = np.argwhere(labels == i)
        if not 300 < len(points) < 10000:
            continue
        lo = points.min(0)
        hi = points.max(0)
        size = hi - lo + 1
        if not 0.5 < size[0] / size[1] < 2 or len(points) / np.prod(size) < 0.45:
            continue
        boundary = nd.binary_dilation(labels == i, iterations=3) & ~(labels == i)
        support = float((boundary & red).sum() / max(boundary.sum(), 1))
        if support < 0.15:
            continue
        candidates.append(dict(pixel=((lo + hi) / 2).tolist(), area=len(points), red_support=support))
    return candidates

def interior_candidates(rgb):
    original = _interior_candidates_kernel(rgb, 3)
    if original:
        return original
    separated = _interior_candidates_kernel(rgb, 11)
    check = _interior_candidates_kernel(rgb, 13)
    if len(separated) != 1 or len(check) != 1:
        return []
    if np.linalg.norm(np.asarray(separated[0]['pixel']) - check[0]['pixel']) > 1.0:
        return []
    return separated

def infer(images, metas):
    candidates = [interior_candidates(image) for image in images]
    valid = []
    for a in candidates[0]:
        for b in candidates[1]:
            try:
                value = triangulate(metas[0], a['pixel'], metas[1], b['pixel'])
                value['xyz'] = value['xyz'].tolist()
                valid.append(value)
            except ValueError:
                continue
    return dict(candidates=candidates, triangulated=valid, abstained=len(valid) != 1)

def run(robo):
    geom = inspect_cup_rim(robo)
    if not grasp_and_lift_bottle(robo, geom, work_arm=geom['work_arm']):
        raise RuntimeError('Planned grasp failed')
    ok, _ = move_mouth_to_stage(robo, geom, work_arm=geom['work_arm'], sign=geom['sign'], roll_mag=60.0, x_mouth_off=-0.024, z_mouth_off=0.075, verify_and_correct=False, stage_label='pre60_before_calibration')
    if not ok:
        raise RuntimeError('Pre60 stage failed')
    measured = inspect_held_mouth_multiview(robo, geom['work_arm'])
    if not measured['mouth_observed']:
        raise RuntimeError('Mouth observation ambiguous')
    mouth = np.asarray(measured['geometry']['triangulated'][0]['xyz'])
    arm = robo.state().arm(geom['work_arm'])
    geom['tcp_to_mouth_eef'] = _quat_to_mat(arm.eef_quat).T @ (mouth - np.asarray(arm.tcp_pos))
    geom['multiview_mouth_calibrated'] = True
    home = robo.home(geom['idle_arm'])
    if not getattr(home, 'reached', False):
        raise RuntimeError('Observer withdrawal failed')
    print('CALIBRATED_GEOMETRY ' + json.dumps(geom, default=lambda x: x.tolist()), flush=True)
    for label, angle, x, z in [('pre82_calibrated', 82.0, -0.022, 0.038), ('early92_calibrated', 92.0, -0.022, 0.034)]:
        ok, diag = move_mouth_to_stage(robo, geom, work_arm=geom['work_arm'], sign=geom['sign'], roll_mag=angle, x_mouth_off=x, z_mouth_off=z, verify_and_correct=True, stage_label=label)
        print('EARLY_GATE', label, ok, diag, flush=True)
        if not ok:
            raise RuntimeError('Early calibrated stage failed ' + label)
    sync = measure_synchronized_mouth(robo, geom)
    print('MOUTH_AFTER ' + json.dumps(sync, default=lambda x: x.tolist()), flush=True)
    for label, angle, x, z, dwell in [('early100', 100.0, -0.021, 0.033, 2), ('early108', 108.0, -0.02, 0.032, 3), ('early116', 116.0, -0.018, 0.032, 3), ('early124', 124.0, -0.016, 0.032, 3)]:
        ok, diag = move_mouth_to_stage(robo, geom, work_arm=geom['work_arm'], sign=geom['sign'], roll_mag=angle, x_mouth_off=x, z_mouth_off=z, verify_and_correct=angle == 100.0, stage_label=label)
        print('POUR_STAGE', label, ok, diag, flush=True)
        if not ok:
            raise RuntimeError('Pour stage failed ' + label)
        _dwell(robo, geom['idle_arm'], dwell)
    drained = run_drain_and_untilt_phase(robo, geom)
    print('DRAIN_COMPLETED', drained, flush=True)
    return {'whole_task_attempt': True, 'drain_returned': bool(drained), 'task_success_claim': False}
import numpy as np

def _fit_upright_mouth(rgb, meta, coarse_xy, spout_z, radius=0.015):
    from scipy import ndimage as nd
    from scipy.optimize import least_squares
    a = np.asarray(rgb, float)
    r, g, b = a.transpose(2, 0, 1)
    K = np.asarray(meta['intrinsic_matrix'])
    T = np.asarray(meta['extrinsic_matrix'])
    coarse = np.asarray(coarse_xy, float)

    def project(xyz):
        camera = (np.asarray(xyz) - T[:3, 3]) @ T[:3, :3]
        if np.any(-camera[:, 2] <= 0):
            raise ValueError('Behind camera')
        return np.column_stack([K[1, 2] - K[1, 1] * camera[:, 1] / -camera[:, 2], K[0, 2] + K[0, 0] * camera[:, 0] / -camera[:, 2]])
    expected = project(np.r_[coarse, spout_z][None, :])[0]
    mask = (r > 15) & (r > g * 1.5) & (r > b * 1.2) & (b > g * 1.1)
    labels, count = nd.label(mask)
    theta = np.linspace(0, 2 * np.pi, 360, endpoint=False)
    valid = []
    for i in range(1, count + 1):
        points = np.argwhere(labels == i)
        if not 20 <= len(points) <= 1500:
            continue
        lo = points.min(0)
        hi = points.max(0)
        if not 5 < hi[1] - lo[1] < 40 or np.linalg.norm(points.mean(0) - expected) > 70:
            continue
        edge = np.asarray([[points[points[:, 1] == x, 0].min(), x] for x in np.unique(points[:, 1])])
        top = points[points[:, 0] <= np.percentile(points[:, 0], 35)].mean(0)
        ray = np.linalg.solve(K, [top[1], top[0], 1.0]) * [1, -1, -1]
        ray = T[:3, :3] @ ray
        if abs(ray[2]) < 1e-06:
            continue
        distance = (spout_z - T[2, 3]) / ray[2]
        if distance <= 0:
            continue
        seed = (T[:3, 3] + distance * ray)[:2]
        if np.any(np.abs(seed - coarse) >= 0.12):
            continue

        def residual(xy):
            circle = np.column_stack([xy[0] + radius * np.cos(theta), xy[1] + radius * np.sin(theta), np.full(len(theta), spout_z)])
            return np.linalg.norm(edge[:, None, :] - project(circle)[None, :, :], axis=2).min(1)
        fits = []
        for delta in ([0, 0], [0.02, 0], [-0.02, 0], [0, 0.02], [0, -0.02]):
            initial = seed + np.asarray(delta)
            if np.any(np.abs(initial - coarse) >= 0.12):
                continue
            attempt = least_squares(residual, initial, bounds=(coarse - 0.12, coarse + 0.12), loss='soft_l1', max_nfev=100)
            if attempt.success:
                fits.append(attempt)
        if not fits:
            continue
        fit = min(fits, key=lambda f: float(np.mean(np.minimum(residual(f.x) ** 2, 9))))
        median = float(np.median(residual(fit.x)))
        if fit.success and median < 0.75:
            valid.append(dict(xy=fit.x.tolist(), median_pixel_residual=median, area=len(points), bounds=[lo.tolist(), hi.tolist()]))
    if len(valid) != 1:
        raise ValueError('Upright mouth boundary ambiguous: ' + str(valid))
    return valid[0]

def _infer_sam_mouth(records, metas):
    pixels = []
    for r in records:
        if not r.get('found') or r.get('score', 0) < 0.5:
            raise ValueError('No confident mouth segment')
        count = r['area_px']
        pixel = r['centroid']
        if pixel is None or len(pixel) != 2:
            raise ValueError('Missing segment centroid')
        if not 300 < count < 10000:
            raise ValueError('Mouth area outside supported range')
        pixels.append(pixel)
    value = triangulate(metas[0], pixels[0], metas[1], pixels[1])
    value['xyz'] = value['xyz'].tolist()
    return dict(candidates=pixels, triangulated=[value], abstained=False)
